const e=JSON.parse(`[{"id":"upsc-2019-prelims-csat-b-001","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":1,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"The number of times the digit 5 will appear while writing the integers from 1 to 1000 is","options":{"a":"269","b":"271","c":"300","d":"302"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"The number of times the digit 5 will appear while writing the integers from 1 to 1000 is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"In 000–999, each of the three digit positions contains 5 exactly 100 times. Counting digit occurrences gives 3 × 100 = 300; the additional number 1000 contains no 5.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-002","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":2,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A solid cube is painted yellow, blue and black such that opposite faces are of same colour. The cube is then cut into 36 cubes of two different sizes such that 32 cubes are small and the other four cubes are Big. None of the faces of the bigger cubes is painted blue. How many cubes have only one face painted?","options":{"a":"4","b":"6","c":"8","d":"10"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"A solid cube is painted yellow, blue and black such that opposite faces are of same colour. The cube is then cut into 36 cubes of two different sizes such that 32 cubes are small and the other four cubes are Big. None of the faces of the bigger cubes is painted blue. How many cubes have only one face painted?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Represent the original cube as a 4 × 4 × 4 array of small-cube units. The four large cubes occupy the central layer without reaching blue faces. Counting the remaining small cubes with exactly one exposed painted face gives 8.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-003","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":3,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A and B are two heavy steel blocks. If B is placed on the top of A, the weight increases by 60%. How much weight will reduce with respect to the total weight of A and B, if B is removed from the top of A?","options":{"a":"60%","b":"45.5%","c":"40%","d":"37.5%"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"A and B are two heavy steel blocks. If B is placed on the top of A, the weight increases by 60%. How much weight will reduce with respect to the total weight of A and B, if B is removed from the top of A?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Take A’s weight as 100. B weighs 60, so removing B reduces the combined weight by 60/160 × 100 = 37.5%.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-004","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":4,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Mr 'X' has three children. The birthday of the first child falls on the 5th Monday of April, that of the second one falls on the 5th Thursday of November. On which day is the birthday of his third child, which falls on 20th December?","options":{"a":"Monday","b":"Thursday","c":"Saturday","d":"Sunday"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Mr 'X' has three children. The birthday of the first child falls on the 5th Monday of April, that of the second one falls on the 5th Thursday of November. On which day is the birthday of his third child, which falls on 20th December?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The fifth Monday and fifth Thursday conditions put 1 November on Thursday. From 1 November to 20 December there are 49 days, exactly seven weeks, so 20 December is Thursday.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-005","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":5,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following Statements and Conclusions:\\n\\nStatements:\\n\\n1. Some rats are cats.\\n\\n2. Some cats are dogs.\\n\\n3. No dog is a cow.\\n\\nConclusions:\\n\\nI. No cow is a cat.\\n\\nII. No dog is a rat.\\n\\nIII. Some cats are rats.\\n\\nWhich of the above conclusions is/are drawn from the statements?","options":{"a":"I, II and III","b":"Only I and II","c":"Only III","d":"Only II and III"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Consider the following Statements and Conclusions:"},{"type":"paragraph","text":"Statements:"},{"type":"paragraph","text":"1. Some rats are cats."},{"type":"paragraph","text":"2. Some cats are dogs."},{"type":"paragraph","text":"3. No dog is a cow."},{"type":"paragraph","text":"Conclusions:"},{"type":"paragraph","text":"I. No cow is a cat."},{"type":"paragraph","text":"II. No dog is a rat."},{"type":"paragraph","text":"III. Some cats are rats."},{"type":"paragraph","text":"Which of the above conclusions is/are drawn from the statements?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Some rats being cats implies that some cats are rats. No statement fixes all cats relative to cows or all dogs relative to rats, so only conclusion III follows.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-006","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":6,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"The number of parallelograms that can be formed from a set of four parallel lines intersecting another set of four parallel lines, is","options":{"a":"18","b":"24","c":"32","d":"36"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"The number of parallelograms that can be formed from a set of four parallel lines intersecting another set of four parallel lines, is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Choose two of the four lines in each parallel family: C(4,2) × C(4,2) = 6 × 6 = 36 parallelograms.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-007","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":7,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In a school every student is assigned a unique identification number. A student is a football player if and only if the identification number is divisible by 4, whereas a student is a cricketer if and only if the identification number is divisible by 6. If every number from 1 to 100 is assigned to a student, then how many of them play cricket as well as football?","options":{"a":"4","b":"8","c":"10","d":"12"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"In a school every student is assigned a unique identification number. A student is a football player if and only if the identification number is divisible by 4, whereas a student is a cricketer if and only if the identification number is divisible by 6. If every number from 1 to 100 is assigned to a student, then how many of them play cricket as well as football?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"A student playing both sports has an ID divisible by LCM(4,6) = 12. There are floor(100/12) = 8 such IDs.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-008","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":8,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"When a runner was crossing the 12 km mark, she was informed that she had completed only 80% of the race. How many kilometres was the runner supposed to run in this event?","options":{"a":"14","b":"15","c":"16","d":"16.5"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"When a runner was crossing the 12 km mark, she was informed that she had completed only 80% of the race. How many kilometres was the runner supposed to run in this event?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"If 12 km is 80% of the race, its full length is 12/0.8 = 15 km.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-009","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":9,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Raju has Rs. 9000 with him and he wants to buy a mobile handset; but he finds that he has only 75% of the amount required to buy the handset. Therefore, he borrows 2000 from a friend. Then","options":{"a":"Raju still does not have enough amount to buy the handset.","b":"Raju has exactly the same amount as required to buy the handset.","c":"Raju has enough amount to buy the handset and he will have 500 with him after buying the handset.","d":"Raju has enough amount to buy the handset and he will have 1000 with him after buying the handset."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Raju has Rs. 9000 with him and he wants to buy a mobile handset; but he finds that he has only 75% of the amount required to buy the handset. Therefore, he borrows 2000 from a friend. Then"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The handset costs 9000/0.75 = Rs. 12,000. After borrowing Rs. 2,000 he has Rs. 11,000, still Rs. 1,000 short.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-010","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":10,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In 2002, Meenu's age was one-third of the age of Meera, whereas in 2010, Meenu's age was half the age of Meera. What is Meenu's year of birth?","options":{"a":"1992","b":"1994","c":"1996","d":"1998"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"In 2002, Meenu's age was one-third of the age of Meera, whereas in 2010, Meenu's age was half the age of Meera. What is Meenu's year of birth?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Let Meenu’s age in 2002 be x and Meera’s be 3x. Eight years later 2(x+8)=3x+8, giving x=8. Meenu was born in 2002−8=1994.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-011","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":11,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Rakesh and Rajesh together bought 10 balls and 10 rackets. Rakesh spent 1300 and Rajesh spent 1500. If each racket costs three times a ball does, then what is the price of a racket?","options":{"a":"Rs. 70","b":"Rs. 90","c":"Rs. 210","d":"Rs. 240"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Rakesh and Rajesh together bought 10 balls and 10 rackets. Rakesh spent 1300 and Rajesh spent 1500. If each racket costs three times a ball does, then what is the price of a racket?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The total cost is Rs. 2,800. With a racket costing 3b and a ball b, 10b + 10(3b) = 2800, so b=70 and a racket costs Rs. 210.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-012","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":12,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In a conference, out of a total 100 participants, 70 are Indians. If 60 of the total participants are vegetarian, then which of the following statements is/are correct?\\n\\n1. At least 30 Indian participants are vegetarian.\\n\\n2. At least 10 Indian participants are non-vegetarian.\\n\\nSelect the correct answer using the codes given below:","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"In a conference, out of a total 100 participants, 70 are Indians. If 60 of the total participants are vegetarian, then which of the following statements is/are correct?"},{"type":"paragraph","text":"1. At least 30 Indian participants are vegetarian."},{"type":"paragraph","text":"2. At least 10 Indian participants are non-vegetarian."},{"type":"paragraph","text":"Select the correct answer using the codes given below:"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The minimum vegetarian Indians are 70+60−100=30. Since there are only 60 vegetarians in total, at least 70−60=10 Indians are non-vegetarian. Both conclusions hold.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-013","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":13,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical, rational and crucial message conveyed by the above passage?","options":{"a":"Public research institutions should take the lead in GM technology and prioritise the technology agenda.","b":"Developing countries should raise this issue in WTO and ensure the abolition of Intellectual Property Rights.","c":"Private corporations should not be allowed to do agribusiness in India, particularly the seed business.","d":"Present Indian circumstances do not favour the cultivation of genetically modified crops."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"What stands in the way of the widespread and careful adoption of 'Genetic Modification (GM)' technology is an \`Intellectual Property Rights' regime that seeks to create private monopolies for such technologies. If GM technology is largely corporate driven, it seeks to maximize profits and that too in the short run. That is why corporations make major investments for herbicide-tolerant and pest-resistant crops. Such properties have only a short window, as soon enough, pests and weeds will evolve to overcome such resistance. This suits the corporations. The National Farmers Commission pointed out that priority must be given in genetic modification to the incorporation of genes that can help impart resistance to drought, salinity and other stresses."},{"type":"paragraph","text":"Which one of the following is the most logical, rational and crucial message conveyed by the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage criticises a private intellectual-property regime that neglects adaptation needs. Its proposed response is public research leadership and a technology agenda suited to farmers, not abolition of all intellectual property or rejection of GM technology.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-014","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":14,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made:\\n\\n1. The issue of effects of natural calamities on agriculture is not given due consideration by GM technology companies.\\n\\n2. In the long run, GM technology will not be able to solve agricultural problems arising due to global warming.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"What stands in the way of the widespread and careful adoption of 'Genetic Modification (GM)' technology is an \`Intellectual Property Rights' regime that seeks to create private monopolies for such technologies. If GM technology is largely corporate driven, it seeks to maximize profits and that too in the short run. That is why corporations make major investments for herbicide-tolerant and pest-resistant crops. Such properties have only a short window, as soon enough, pests and weeds will evolve to overcome such resistance. This suits the corporations. The National Farmers Commission pointed out that priority must be given in genetic modification to the incorporation of genes that can help impart resistance to drought, salinity and other stresses."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made:"},{"type":"paragraph","text":"1. The issue of effects of natural calamities on agriculture is not given due consideration by GM technology companies."},{"type":"paragraph","text":"2. In the long run, GM technology will not be able to solve agricultural problems arising due to global warming."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage supports the concern that corporate priorities overlook farmers’ adaptation to natural calamities. It does not establish that GM technology can never help with global-warming problems.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-015","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":15,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical and rational inference that can be made from the above passage?","options":{"a":"Invasive species should be used to rehabilitate desert areas and wastelands of a country.","b":"Laws against the introduction of foreign plants are unnecessary.","c":"Sometimes, the campaigns against foreign plants are pointless.","d":"Foreign plants should be used to increase the biodiversity of a country."},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Most invasive species are neither terribly successful nor very harmful. Britain's invasive plants are not widespread, not spreading especially quickly, and often less of a nuisance than vigorous natives such as bracken. The arrival of new species almost always increases biological diversity in a region; in many cases, a flood of newcomers drives no native species to extinction. One reason is that invaders tend to colonise disturbed habitats like polluted lakes and post-industrial wasteland, where little else lives. They are nature's opportunists."},{"type":"paragraph","text":"Which one of the following is the most logical and rational inference that can be made from the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage describes introduced plants that are neither highly successful nor especially harmful. The limited inference is that campaigns against foreign plants can sometimes be pointless, not that all introductions are desirable.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-016","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":16,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made:\\n\\n1. Food safety is a complex issue that calls for a multipronged solution.\\n\\n2. Great investments need to be made in developing the manpower for surveillance and training.\\n\\n3. India needs to make sufficient legislation for governing food processing industry.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 and 2 only","b":"3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Diarrhoeal deaths among Indian children are mostly due to food and water contamination. Use of contaminated groundwater and unsafe chemicals in agriculture, poor hygiene in storage and handling of food items to food cooked and distributed in unhygienic surroundings; there are myriad factors that need regulation and monitoring. People need to have awareness of adulteration and ways of complaining to the relevant authorities. Surveillance of food-borne diseases involves a number of government agencies and entails good training of inspection staff. Considering the proportion of the urban population that depends on street food for its daily meals, investing in training and education of street vendors is of great significance."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made:"},{"type":"paragraph","text":"1. Food safety is a complex issue that calls for a multipronged solution."},{"type":"paragraph","text":"2. Great investments need to be made in developing the manpower for surveillance and training."},{"type":"paragraph","text":"3. India needs to make sufficient legislation for governing food processing industry."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The many contamination pathways require a multipronged response. The passage also stresses trained inspection staff and vendor education. It does not establish that insufficient legislation is the necessary missing element, so assumptions 1 and 2 are accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-017","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":17,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The passage seems to argue","options":{"a":"against the monopoly of builders and the interests of elite groups.","b":"against the need for global and smart cities.","c":"in favour of planning cities mainly for working class and poor people.","d":"in favour of participation of peoples' groups in city planning."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"The interests of working and poor people have historically been neglected in the planning of our cities. Our cities are increasingly intolerant,', unsafe and unlivable places for large numbers of citizens and yet we continue to plan via the old ways — the static Development Plan — that draws exclusively from technical expertise, distanced from people's live experiences and needs, and actively excluding large number of people, places, activities and practices that are an integral part of the city."},{"type":"paragraph","text":"The passage seems to argue"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The argument calls for participatory planning that gives working people and the poor a voice. This supports participation of people’s groups, rather than a blanket rejection of global or smart cities.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-018","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":18,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The above passage seems to imply that\\n\\n1. most of modern economic growth is based on technological progress.\\n\\n2. much of modern Indian economy does not nurture sufficient symbiotic relationship with labour-intensive, natural resource-based livelihoods.\\n\\n3. service sector in India is not very labour-intensive.\\n\\n4. literate rural population is not willing to enter organised sector.\\n\\nWhich of the statements given above are correct?","options":{"a":"1 and 2 only","b":"3 and 4 only","c":"1, 2 and 3 only","d":"1, 2, 3 and 4"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"A vast majority of Indians are poor, with barely 10 percent employed in the organised sector. We are being convinced that vigorous economic growth is generating substantial employment. But this is not so. When our economy was growing at 3 percent per year, employment in the organised sector was growing at 2 percent per year. As the economy began to grow at 7 - 8 percent per year, the rate of growth of employment in the organised sector actually declined to 1 percent per year."},{"type":"paragraph","text":"The above passage seems to imply that"},{"type":"paragraph","text":"1. most of modern economic growth is based on technological progress."},{"type":"paragraph","text":"2. much of modern Indian economy does not nurture sufficient symbiotic relationship with labour-intensive, natural resource-based livelihoods."},{"type":"paragraph","text":"3. service sector in India is not very labour-intensive."},{"type":"paragraph","text":"4. literate rural population is not willing to enter organised sector."},{"type":"paragraph","text":"Which of the statements given above are correct?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage contrasts technology-led organised growth with poor people’s livelihoods and the limited labour absorption of services. Statements 1, 2 and 3 follow; it does not say literate rural people refuse organised-sector work.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-019","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":19,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical, rational and crucial inference that can be derived from the above passage?","options":{"a":"Efforts to bring people in India's hinterland into the banking system are not successful.","b":"For meaningful financial inclusion, India's banking system needs more number of banking correspondents and other such last-mile workers.","c":"Meaningful financial inclusion in India requires that banking correspondents have diverse skills","d":"Better banking outreach would be impossible unless each banking correspondent is allowed to serve a number of banks"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"India has banking correspondents, who help bring people in the hinterland into the banking fold. For them to succeed, banks cannot crimp on costs. They also cannot afford to ignore investing in financial education and literacy. Banking correspondents are way too small to be viewed as a systemic risk. Yet India's banking regulator has restricted them to serving only one bank, perhaps to prevent arbitrage.'Efforts at banking outreach may succeed only if there are better incentives at work for such last-mile workers and also those providers who ensure not just basic bank accounts but also products such as accident and life insurance and micro pension schemes."},{"type":"paragraph","text":"Which one of the following is the most logical, rational and crucial inference that can be derived from the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Banking correspondents need more than low-cost transaction delivery: their work calls for appropriate capabilities and skills. The passage does not establish that simply increasing their number or letting each serve many banks is sufficient.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-020","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":20,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A five-storeyed building with floors from I to V is painted using four different colours and only one colour is used to paint a floor.\\n\\nConsider the following statements:\\n\\n1. The middle three floors are painted in different colours.\\n\\n2. The second (II) and the fourth (IV) floors are painted in different colours.\\n\\n3. The first (I) and the fifth (V) floors are painted red.\\n\\nTo ensure that any two consecutive floors have different colours","options":{"a":"Only statement 2 is sufficient","b":"Only statement 3 is sufficient","c":"Statement 1 is not sufficient, but statement 1 along with statement 2 is sufficient","d":"Statement 3 is not sufficient, but statement 3 along with statement 2 is sufficient"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"A five-storeyed building with floors from I to V is painted using four different colours and only one colour is used to paint a floor."},{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. The middle three floors are painted in different colours."},{"type":"paragraph","text":"2. The second (II) and the fourth (IV) floors are painted in different colours."},{"type":"paragraph","text":"3. The first (I) and the fifth (V) floors are painted red."},{"type":"paragraph","text":"To ensure that any two consecutive floors have different colours"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"All four colours must be used across the five floors. If floors I and V are red, the three remaining floors must use the other three colours, which guarantees different colours on adjacent floors. Statement 3 is sufficient.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-021","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":21,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"P, Q and R are three towns. The distance between P and Q is 60 km, whereas the distance between P and R is 80 km. Q is in the West of P and R is in the South of P. What is the distance between Q and R?","options":{"a":"140 km","b":"130 km","c":"10 km","d":"100 km"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"P, Q and R are three towns. The distance between P and Q is 60 km, whereas the distance between P and R is 80 km. Q is in the West of P and R is in the South of P. What is the distance between Q and R?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The westward and southward distances form a right triangle. QR = sqrt(60²+80²) = 100 km.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-022","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":22,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"All members of a club went to Mumbai and stayed in a hotel. On the first day, 80% went for shopping and 50% went for sightseeing, whereas 10% took rest in the hotel. Which of the following conclusion(s) can be drawn from the above data?\\n\\n1. 40% members went for shopping as well as sightseeing.\\n\\n2. 20% members went for only shopping.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"All members of a club went to Mumbai and stayed in a hotel. On the first day, 80% went for shopping and 50% went for sightseeing, whereas 10% took rest in the hotel. Which of the following conclusion(s) can be drawn from the above data?"},{"type":"paragraph","text":"1. 40% members went for shopping as well as sightseeing."},{"type":"paragraph","text":"2. 20% members went for only shopping."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Ninety percent took part in at least one activity. The overlap is 80+50−90=40%. Shopping only is 80−40=40%, not 20%; only conclusion 1 follows.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-023","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":23,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In a school, 60% students play cricket. A student who does not play cricket, plays football. Every football player has got a two-wheeler. Which of the following conclusions cannot be drawn from the above data?\\n\\n1. 60% of the students do not have two-wheelers.\\n\\n2. No cricketer has a two-wheeler.\\n\\n3. Cricket players do not play football.\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"In a school, 60% students play cricket. A student who does not play cricket, plays football. Every football player has got a two-wheeler. Which of the following conclusions cannot be drawn from the above data?"},{"type":"paragraph","text":"1. 60% of the students do not have two-wheelers."},{"type":"paragraph","text":"2. No cricketer has a two-wheeler."},{"type":"paragraph","text":"3. Cricket players do not play football."},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The data guarantee football for non-cricketers and two-wheelers for footballers, but do not exclude cricket players from football or two-wheeler ownership. None of the three negative conclusions is guaranteed.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-024","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":24,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"The ratio of a two-digit natural number to a number formed by reversing its digits is 4: 7. The number of such pairs is","options":{"a":"5","b":"4","c":"3","d":"2"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"The ratio of a two-digit natural number to a number formed by reversing its digits is 4: 7. The number of such pairs is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"For digits a,b, 7(10a+b)=4(10b+a), so b=2a. The four digit pairs are (1,2), (2,4), (3,6) and (4,8).","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-025","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":25,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In an examination, A has scored 20 marks more than B. If B has scored 5% less marks than A, how much has B scored?","options":{"a":"360","b":"380","c":"400","d":"420"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"In an examination, A has scored 20 marks more than B. If B has scored 5% less marks than A, how much has B scored?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The 20-mark difference is 5% of A’s marks. A=20/0.05=400 and B=400−20=380.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-026","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":26,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Seeta and Geeta go for a swim after a gap of every 2 days and every 3 days respectively. If on 1st January both of them went for a swim together, when will they go together next?","options":{"a":"7th January","b":"8th January","c":"12th January","d":"13th January"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Seeta and Geeta go for a swim after a gap of every 2 days and every 3 days respectively. If on 1st January both of them went for a swim together, when will they go together next?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"A gap of two days means a three-day interval and a gap of three days means a four-day interval. LCM(3,4)=12 days after 1 January gives 13 January.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-027","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":27,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"X, Y and Z are three contestants in a race of 1000 m. Assume that all run with different uniform speeds. X gives Y a start of 40 m and X gives Z a start of 64 m. If Y and Z were to compete in a race of 1000 m, how many metres start will Y give to Z?","options":{"a":"20","b":"25","c":"30","d":"35"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"X, Y and Z are three contestants in a race of 1000 m. Assume that all run with different uniform speeds. X gives Y a start of 40 m and X gives Z a start of 64 m. If Y and Z were to compete in a race of 1000 m, how many metres start will Y give to Z?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Y covers 960 m in the time Z covers 936 m. For Y’s 1000 m, Z covers 1000 × 936/960=975 m, giving a 25 m start.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-028","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":28,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If x is greater than or equal to 25 and y is less than or equal to 40, then which one of the following is always correct?","options":{"a":"x is greater than y","b":"(y - x) is'greater than 15","c":"(y - x) is less than or equal to 15","d":"(x - y) is greater than or equal to 65"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"If x is greater than or equal to 25 and y is less than or equal to 40, then which one of the following is always correct?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The greatest possible y−x is 40−25=15. Thus y−x is always at most 15, even though x and y need not be ordered the same way in every case.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-029","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":29,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Ena was born 4 years after her parents' marriage. Her mother is three years younger than her father and 24 years older than Ena, who is 13 years old. At what age did Ena's father get married?","options":{"a":"22 years","b":"23 years","c":"24 years","d":"25 years"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Ena was born 4 years after her parents' marriage. Her mother is three years younger than her father and 24 years older than Ena, who is 13 years old. At what age did Ena's father get married?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The mother is 13+24=37 and the father is 40. The marriage was 13+4=17 years ago, so the father married at 40−17=23.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-030","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":30,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Rakesh had money to buy 8 mobile handsets of a specific company. But the retailer offered very good discount on that particular handset. Rakesh could buy 10 mobile handsets with the amount he had. What was the discount the retailer offered?","options":{"a":"15%","b":"20%","c":"25%","d":"30%"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Rakesh had money to buy 8 mobile handsets of a specific company. But the retailer offered very good discount on that particular handset. Rakesh could buy 10 mobile handsets with the amount he had. What was the discount the retailer offered?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The available money is eight full-price handsets but ten discounted handsets. The new price is 8/10 of the old price, a 20% discount.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-031","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":31,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"The average marks of 100 students are given to be 40. It was found later that marks of one student were 53 which were misread as 83. The corrected mean marks are","options":{"a":"39","b":"39.7","c":"40","d":"40.3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"The average marks of 100 students are given to be 40. It was found later that marks of one student were 53 which were misread as 83. The corrected mean marks are"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Correct the total by subtracting the excess 83−53=30. The mean becomes (4000−30)/100=39.7.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-032","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":32,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following statements is the most logical and rational inference that can be made from the above passage?","options":{"a":"Development of enabling technologies in India can be a big boost to its manufacturing sector.","b":"India is not yet fully ready to adopt IoT in view of the imminent security challenges.","c":"Life becomes more comfortable with the development of cheap low-end IoT devices.","d":"As we go digital, we must recognise the huge threat to Internet security from some IoT devices."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Low-end IoT (Internet of Things) devices are cheap commodity items: addressing security would add to the cost. This class of items is proliferating with new applications; many home appliances, thermostats, security and monitoring devices and personal convenience devices are part of the IoT. So are fitness trackers, certain medical implants and computer-like devices in automobiles. The IoT is expected to expand exponentially — but new security challenges are daunting."},{"type":"paragraph","text":"Which one of the following statements is the most logical and rational inference that can be made from the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage connects cheap, proliferating IoT devices with inadequate security. Its inference is the need to recognise the resulting Internet-security threat as digitisation expands.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-033","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":33,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical and rational corollary to the above passage?","options":{"a":"Globalization is not in the interests of India as it undermines its socio-economic structures.","b":"India should be careful to protect its digital sovereignty in global trade talks.","c":"India should charge monopoly rents from multinational companies in exchange for Big Data.","d":"The loss of Big Data from India is proportional to the degree/value of its foreign trade."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"With the digital phenomenon restructuring most social sectors, it is little surprise that global trade negotiations are now eyeing the digital area in an attempt to pre-emptively colonise it. Big Data is freely collected or mined from developing countries, and converted into digital intelligence in developed countries. This intelligence begins to control different sectors and extract monopoly rents. A large foreign company providing cab service, for instance, is not a work of cars and drivers, it is digital intelligence about commuting, public transport, roads, traffic, city events, presonal behavioural characteristics of commuters and driver and so on."},{"type":"paragraph","text":"Which one of the following is the most logical and rational corollary to the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The trade argument treats data as a strategic resource that can shift control and value abroad. Protecting India’s digital sovereignty follows, without requiring rejection of all global trade.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-034","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":34,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is most definitively implied by the above passage?","options":{"a":"7 Big Data is the key resource in the digital space.","b":"Big economies create Big Data.","c":"Access to Big Data is the prerogative of developed countries.","d":"Access to and possession of Big Data is a characteristic of developed countries."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"With the digital phenomenon restructuring most social sectors, it is little surprise that global trade negotiations are now eyeing the digital area in an attempt to pre-emptively colonise it. Big Data is freely collected or mined from developing countries, and converted into digital intelligence in developed countries. This intelligence begins to control different sectors and extract monopoly rents. A large foreign company providing cab service, for instance, is not a work of cars and drivers, it is digital intelligence about commuting, public transport, roads, traffic, city events, presonal behavioural characteristics of commuters and driver and so on."},{"type":"paragraph","text":"Which of the following is most definitively implied by the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The argument depends on Big Data being a key resource in the digital economy. It does not say that only developed countries can own or access data.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-035","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":35,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the most logical and rational Corry to the above passage?","options":{"a":"Supporting small farmers is an important part of any agenda regarding environmentally sustainable development.","b":"Poor countries have little role to play in the mitigation of global warming.","c":"Due to a large number of farmer households, India will not have food security problem in the foreseeable future.","d":"Only small-holder farmers in India can ensure food security."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"The rural poor across the world, including India, have contributed little to human-induced climate change, yet they are on the frontline in coping with its effects. Farmers can no longer rely on historical averages for rainfall and temperature, and the more frequent and extreme weather events, such as droughts and floods, can spell disaster. And there are new threats, such as sea level rise and the impact of melting glaciers on water supply. How significant are small farms? As many as two billion peopre worldwide depend on them for their food and livelihood. Small-holder farmers in India produce 41 percent of the country's food grains, and other food items that contribute to local and national food security."},{"type":"paragraph","text":"What is the most logical and rational Corry to the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Small farmers have contributed little to climate change but face major risks. Supporting them therefore belongs in an environmentally sustainable development agenda.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-036","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":36,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The above passage implies that\\n\\n1. There is a potential problem of food insecurity in India.\\n\\n2. India will have to strengthen its disaster management capabilities.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"The rural poor across the world, including India, have contributed little to human-induced climate change, yet they are on the frontline in coping with its effects. Farmers can no longer rely on historical averages for rainfall and temperature, and the more frequent and extreme weather events, such as droughts and floods, can spell disaster. And there are new threats, such as sea level rise and the impact of melting glaciers on water supply. How significant are small farms? As many as two billion peopre worldwide depend on them for their food and livelihood. Small-holder farmers in India produce 41 percent of the country's food grains, and other food items that contribute to local and national food security."},{"type":"paragraph","text":"The above passage implies that"},{"type":"paragraph","text":"1. There is a potential problem of food insecurity in India."},{"type":"paragraph","text":"2. India will have to strengthen its disaster management capabilities."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage links climate threats to farming and food supply and points to responses to extreme events. It supports both a food-insecurity risk and the need for stronger disaster-management capacity.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-037","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":37,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made:\\n\\n1. Governments and companies need to be adequately prepared to face the climate change.\\n\\n2. Extreme weather events will reduce the economic growth of governments and companies'in future.\\n\\n3. Ignoring climate change is a huge risk for investors.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 and 2 only","b":"3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"A changing climate, and the eventual efforts of governments (however reluctant) to deal with it, could have a big impact on investors' returns. Companies that produce or use large amounts of fossil fuels will face higher taxes and regulatory burdens. Some energy producers may find it impossible to exploit their known reserves, and be left with \\"stranded assets\\" — deposits of oil and coal that have to be left in the ground. Other industries could be affected by the economic damage caused by more extreme weather — storms, floods, heat waves and droughts."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made:"},{"type":"paragraph","text":"1. Governments and companies need to be adequately prepared to face the climate change."},{"type":"paragraph","text":"2. Extreme weather events will reduce the economic growth of governments and companies'in future."},{"type":"paragraph","text":"3. Ignoring climate change is a huge risk for investors."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage treats climate risk as relevant to institutional preparedness and investment decisions. Assumptions 1 and 3 are accepted; an inevitable reduction in every government’s or company’s future growth is too strong.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-038","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":38,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made:\\n\\n1. Making equality of opportunity a reality is the fundamental goal of the Indian education system.\\n\\n2. The present Indian school system is unable to provide egalitarian education.\\n\\n3. Abolition of private schools and establishment of more government schools is the only way to ensure egalitarian education.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 and 2 only","b":"2 only","c":"2 and 3 only","d":"3 only"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Access to schooling for those coming of school age is close to universal, but access to quality exhibits a sharp gradient with socio-economic status. Quotas for the weaker sections in private schools is a provision introduced by the Right of Children to Free and Compulsory Education Act, 2009. The quotas have imposed a debate on issues of social integration and equity in education that private actors had escaped by and large, The idea of egalitarian education system with equality of opportunity as its primary goal appears to be outside the space that private school principals inhabit. Therefore, the imposition of the quotas has led to resistance, sometimes justified,"},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made:"},{"type":"paragraph","text":"1. Making equality of opportunity a reality is the fundamental goal of the Indian education system."},{"type":"paragraph","text":"2. The present Indian school system is unable to provide egalitarian education."},{"type":"paragraph","text":"3. Abolition of private schools and establishment of more government schools is the only way to ensure egalitarian education."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage criticises the present school system’s failure to deliver egalitarian education. It does not establish either the asserted fundamental goal or abolition of private schools as the only solution. Only assumption 2 is accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-039","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":39,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical, rational and crucial message conveyed by the above passage?","options":{"a":"TB is not a curable disease in Indian circumstances.","b":"Curing TB requires more than diagnosis and medical treatment.","c":"Government's surveillance mechanism is deficient; and poor people have no access to treatment.","d":"India will be free from diseases like TB only when its poverty alleviation programmes are effectively and successfully implemented."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"A majority of the TB infected in India are poor and lack sufficient nutrition, suitable housing and have little understanding of prevention. TB then devastates families, makes the poor poorer, particularly affects women and children, and leads to ostracisation and loss of employment. The truth is that even if TB does not kill them, hunger and poverty will. Another truth is that deep-seated stigma, lack of\\n\\ncounselling, expensive treatment and lack of adequate support from providers and family, coupled with torturous side-effects demotivate patients to continue treatment — with disastrous health consequences."},{"type":"paragraph","text":"Which one of the following is the most logical, rational and crucial message conveyed by the above passage?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The argument links TB outcomes with social and economic conditions as well as treatment. The crucial message is that diagnosis and medication alone do not address all obstacles to curing it.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-040","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":40,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If every alternative letter of the English alphabet from B onwards (including B) is written in lower case (small letters) and the remaining letters are capitalized, then how is the first month of the second half of the year written?","options":{"a":"JuLY","b":"jULy","c":"jUly","d":"jUlY"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"If every alternative letter of the English alphabet from B onwards (including B) is written in lower case (small letters) and the remaining letters are capitalized, then how is the first month of the second half of the year written?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Even-position letters are lowercase and odd-position letters uppercase. J(10), u(21), l(12), y(25) therefore give jUlY.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-041","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":41,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Sunita cuts a sheet of paper into three pieces. Length of first piece is equal to the average of the three single digit odd prime numbers. Length of the second piece is equal to that of the first plus one-third the length of the third. The third piece is as long as the other two pieces together. The length of the original sheet of paper is","options":{"a":"13 units","b":"15 units","c":"16 units","d":"30 units"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Sunita cuts a sheet of paper into three pieces. Length of first piece is equal to the average of the three single digit odd prime numbers. Length of the second piece is equal to that of the first plus one-third the length of the third. The third piece is as long as the other two pieces together. The length of the original sheet of paper is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The first piece is (3+5+7)/3=5. Let the third be z; the second is 5+z/3 and z=5+(5+z/3), so z=15. Total length is 5+10+15=30.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-042","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":42,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In the sequence 1, 5, 7, 3, 5, 7, 4, 3, 5, 7, how many such 5s are there which are not immediately preceded by 3 but are immediately followed by 7?","options":{"a":"1","b":"2","c":"3","d":"None"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"In the sequence 1, 5, 7, 3, 5, 7, 4, 3, 5, 7, how many such 5s are there which are not immediately preceded by 3 but are immediately followed by 7?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Inspect each occurrence of 5. Two have a following 7 and a preceding number other than 3, so the required count is 2.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-043","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":43,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A joint family consists of seven members A, B, C, D, E, F and G with three females. G is a widow and sister-in-law of D's father F. B and D are siblings and A is daughter of B. C is cousin of B. Who is E?\\n\\n1. Wife of F\\n\\n2. Grandmother of A\\n\\n3. Aunt of C\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"A joint family consists of seven members A, B, C, D, E, F and G with three females. G is a widow and sister-in-law of D's father F. B and D are siblings and A is daughter of B. C is cousin of B. Who is E?"},{"type":"paragraph","text":"1. Wife of F"},{"type":"paragraph","text":"2. Grandmother of A"},{"type":"paragraph","text":"3. Aunt of C"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"A and G account for two females. E is F’s wife, making her A’s grandmother and the aunt of B’s cousin C. All three descriptions apply.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-044","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":44,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Each face of a cube can be painted in black or white colours. In how many different ways can the cube be painted?","options":{"a":"9","b":"10","c":"11","d":"12"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Each face of a cube can be painted in black or white colours. In how many different ways can the cube be painted?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Count colourings up to rotation by the number of white faces. The counts for 0,1,2,3,4,5,6 white faces are 1,1,2,2,2,1,1, giving 10.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-045","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":45,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"How many triplets (x, y, z) satisfy the equation x + y + z = 6, where x, y and z are natural numbers?","options":{"a":"4","b":"5","c":"9","d":"10"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"How many triplets (x, y, z) satisfy the equation x + y + z = 6, where x, y and z are natural numbers?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Natural numbers here are positive. The number of positive solutions of x+y+z=6 is C(5,2)=10.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-046","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":46,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If $ means 'divided by'; @ means 'multiplied by'; # means 'minus', then the value of 10#5@1$5 is","options":{"a":"0","b":"1","c":"2","d":"9"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"If $ means 'divided by'; @ means 'multiplied by'; # means 'minus', then the value of 10#5@1$5 is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Apply multiplication and division before subtraction: 10−5×1/5=10−1=9.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-047","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":47,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"An 8-digit number 4252746B leaves remainder 0 when divided by 3. How many values of B are possible?","options":{"a":"2","b":"3","c":"4","d":"6"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"An 8-digit number 4252746B leaves remainder 0 when divided by 3. How many values of B are possible?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The fixed digits sum to 30. Divisibility by 3 allows B=0,3,6,9, hence four possible values.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-048","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":48,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"If F stands second in the ranking, then the position of B is","options":{"a":"Third","b":"Fourth","c":"Fifth","d":"Sixth"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Six students A, B, C, D, E and F appeared in several tests. Either C or F scores the highest. Whenever C scores the highest, then E scores the least. Whenever F scores the highest, B scores the least. In all the tests they got different marks; D scores higher than A, but they are close competitors; A scores higher than B; C scores higher than A."},{"type":"paragraph","text":"If F stands second in the ranking, then the position of B is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"With F second, C must be first and E last. The inequalities put D and A ahead of B, so B is fifth.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-049","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":49,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"If B scores the least, the rank of C will be","options":{"a":"Second","b":"Third","c":"Fourth","d":"Second or third"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Six students A, B, C, D, E and F appeared in several tests. Either C or F scores the highest. Whenever C scores the highest, then E scores the least. Whenever F scores the highest, B scores the least. In all the tests they got different marks; D scores higher than A, but they are close competitors; A scores higher than B; C scores higher than A."},{"type":"paragraph","text":"If B scores the least, the rank of C will be"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"If B is last, F is first. C must be above A, but its relation to D is not fixed, allowing C to be second or third.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-050","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":50,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"If E is ranked third, then which one of the following is correct?","options":{"a":"E gets more marks than C","b":"C gets more marks than E","c":"A is ranked fourth","d":"D is ranked fifth"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Six students A, B, C, D, E and F appeared in several tests. Either C or F scores the highest. Whenever C scores the highest, then E scores the least. Whenever F scores the highest, B scores the least. In all the tests they got different marks; D scores higher than A, but they are close competitors; A scores higher than B; C scores higher than A."},{"type":"paragraph","text":"If E is ranked third, then which one of the following is correct?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"E being third prevents C from being first, since that would force E last. F is first and C lies above E; therefore C gets more marks than E.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-051","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":51,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following statements is correct?","options":{"a":"Weight of Mohan is greatest","b":"Weight of Sohan is greatest","c":"Weight of Rohan is greatest","d":"Whose weight is greatest' cannot be determined"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"S1: Twice the weight of Sohan is less than the weight of Mohan or that of Rohan.\\n\\nS2: Twice the weight of Rohan is greater than the weight of Mohan or that of Sohan."},{"type":"paragraph","text":"Which one of the following statements is correct?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Sohan is lighter than both others, but the inequalities allow either Mohan or Rohan to be the greatest. The greatest weight cannot be uniquely determined.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-052","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":52,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following statements is correct?","options":{"a":"Weight of Mohan is least","b":"Weight of Sohan is least","c":"Weight of Rohan is least","d":"'Whose weight is least' cannot be determined"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"S1: Twice the weight of Sohan is less than the weight of Mohan or that of Rohan.\\n\\nS2: Twice the weight of Rohan is greater than the weight of Mohan or that of Sohan."},{"type":"paragraph","text":"Which one of the following statements is correct?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"S1 gives 2×Sohan less than both Mohan and Rohan, so Sohan is necessarily the lightest.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-053","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":53,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical, rational and crucial inference that can be derived from the above passage ?","options":{"a":"A better regulatory system will help India achieve the size of economy appropriate to its population.","b":"In a competitive global economy, India must use regulations strategically.","c":"Regulations in India do not favour its integration with today's hyper competitive global economy.","d":"Job creation and economic growth should be dominant considerations in developing India's regulatory system."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"India's economic footprint, given its population, still remains small compared to the US, the European Union or China. It has much to learn from other economies, yet must implement solutions that fit its unique circumstances. India especially needs an effective long-term regulatory system based on collaboration rather than the ' current top-down approach. Regulations seek desirable outcomes yet are repeatedly used as political tools to push one agenda or another. Often, regulations fail to consider impacts on jobs and economic growth — or less restrictive alternatives. Regulations may be used to protect local markets at the expense of more widely shared prosperity in the future. Additionally, regulations inevitably result in numerous unintended consequences. In today's hyper competitive global economy, regulations need to be viewed as \\"weapons\\" that seek cost-justified social and environmental benefits while improving the economic well-being of most citizens."},{"type":"paragraph","text":"Which one of the following is the most logical, rational and crucial inference that can be derived from the above passage ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage argues that regulation should be assessed in the context of jobs and economic growth. This supports making those considerations central when developing India’s regulatory system.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-054","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":54,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\nIn today's global economy,\\n\\n1. regulations are not effectively used to protect local markets.\\n\\n2. social and environmental concerns are generally ignored by the governments across the world while implementing the regulations.\\n\\nWhich of the above assumptions is/are valid ?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"India's economic footprint, given its population, still remains small compared to the US, the European Union or China. It has much to learn from other economies, yet must implement solutions that fit its unique circumstances. India especially needs an effective long-term regulatory system based on collaboration rather than the ' current top-down approach. Regulations seek desirable outcomes yet are repeatedly used as political tools to push one agenda or another. Often, regulations fail to consider impacts on jobs and economic growth — or less restrictive alternatives. Regulations may be used to protect local markets at the expense of more widely shared prosperity in the future. Additionally, regulations inevitably result in numerous unintended consequences. In today's hyper competitive global economy, regulations need to be viewed as \\"weapons\\" that seek cost-justified social and environmental benefits while improving the economic well-being of most citizens."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"In today's global economy,"},{"type":"paragraph","text":"1. regulations are not effectively used to protect local markets."},{"type":"paragraph","text":"2. social and environmental concerns are generally ignored by the governments across the world while implementing the regulations."},{"type":"paragraph","text":"Which of the above assumptions is/are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage does not establish that regulations fail to protect local markets everywhere or that governments generally ignore social and environmental concerns. Neither broad assumption is justified.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-055","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":55,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical, rational and crucial inference that can be derived from the above passage ?","options":{"a":"If malnourished condition in children is caused by gut bacteria, it cannot be treated.","b":"The guts of malnourished babies should be inoculated with mature microbiomes.","c":"Babies of malnourished mothers should be fed with dairy milk fortified with sialylated oligosaccharides instead of mother's milk.","d":"Research on benign effects of gut bacteria on nutrition has policy implications."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"In a study, scientists compared the microbiomes of poorly nourished and well nourished infants and young children. Gut microbes were isolated from faecal samples of malnourished and healthy children. The microbiome was \\"immature\\" and less diverse in malnourished children compared to the better developed \\"mature\\" microbiome found in healthy children of the same age. According to some studies, the chemical composition of mother's milk has shown the presence of a modified sugar (sialylated oligosaccharides). This is not utilized by the baby for its own nutrition. However, the bacteria constituting the infant's microbiome thrive on this sugar which serves as their food. Malnourished mothers have low levels of this sugar in their milk. Consequently, the microbiomes of their infants fail to mature. That in\\n\\nturn, leads to malnourished babies."},{"type":"paragraph","text":"Which one of the following is the most logical, rational and crucial inference that can be derived from the above passage ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The research connects gut microbiomes, maternal nutrition and infant nutrition. Its cautious policy implication is that these biological findings matter for nutrition policy; it does not justify the specific treatments in the other choices.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-056","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":56,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\n1. Processed probiotic foods are a solution to treat the children suffering from malnutrition due to immature gut bacteria composition.\\n\\n2. The babies of malnourished mothers generally tend to be' malnourished. Which of the above assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"In a study, scientists compared the microbiomes of poorly nourished and well nourished infants and young children. Gut microbes were isolated from faecal samples of malnourished and healthy children. The microbiome was \\"immature\\" and less diverse in malnourished children compared to the better developed \\"mature\\" microbiome found in healthy children of the same age. According to some studies, the chemical composition of mother's milk has shown the presence of a modified sugar (sialylated oligosaccharides). This is not utilized by the baby for its own nutrition. However, the bacteria constituting the infant's microbiome thrive on this sugar which serves as their food. Malnourished mothers have low levels of this sugar in their milk. Consequently, the microbiomes of their infants fail to mature. That in\\n\\nturn, leads to malnourished babies."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Processed probiotic foods are a solution to treat the children suffering from malnutrition due to immature gut bacteria composition."},{"type":"paragraph","text":"2. The babies of malnourished mothers generally tend to be' malnourished. Which of the above assumptions is/are valid?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The discussion of maternal nutrition and infant outcomes supports assumption 2. It does not establish processed probiotic foods as a proven treatment for the stated problem.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-057","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":57,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been Made :\\n\\n1. Regions of glaciers warm faster than other regions due to global warming.\\n\\n2. Global warming can lead to seafloor sedimentation in some areas.\\n\\n3. Melting glaciers can reduce marine biodiversity in some areas.\\n\\nWhich of the above assumptions is/are valid?","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Temperatures have risen nearly five times as rapidly on the Western Antarctic Peninsula than the global average over the past five decades. Researchers have now found that melting glaciers are causing a loss of species diversity among benthos in the coastal waters off the Antarctic Peninsula, Impacting an entire seafloor ecosystem. They Believe increased levels of suspended sediment in water to be the cause of the dwindling biodiversity in the coastal region."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been Made :"},{"type":"paragraph","text":"1. Regions of glaciers warm faster than other regions due to global warming."},{"type":"paragraph","text":"2. Global warming can lead to seafloor sedimentation in some areas."},{"type":"paragraph","text":"3. Melting glaciers can reduce marine biodiversity in some areas."},{"type":"paragraph","text":"Which of the above assumptions is/are valid?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Glacial melt can increase sediment reaching the seabed and affect marine habitats. Statements 2 and 3 are supported; faster warming of every glacial region is not established by the passage.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-058","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":58,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\n1. Global warming is a frequently occurring natural phenomenon.\\n\\n2. The impending global warming will not adversely affect small mammals.\\n\\n3. Humans are responsible for the loss of the Earth's natural resilience.\\n\\nWhich of the above assumptions is/are valid ?","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"A research team examined a long-term owl roost. Owls prey on small mammals and the excreted remains of those meals that accumulated over the time, provide us an insight into the composition and structure of small mammals over the past 'millennia. The research suggested that when the Earth went through a period of rapid warming about 13,000 years ago, the small mammal community was stable and resilient. But, from the last quarter of the nineteenth century, human-made changes to the environment had caused an enormous drop in biomass and energy flow. This dramatic decline in energy flow means modern ecosystems are not adapting as easily as they did in the past."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Global warming is a frequently occurring natural phenomenon."},{"type":"paragraph","text":"2. The impending global warming will not adversely affect small mammals."},{"type":"paragraph","text":"3. Humans are responsible for the loss of the Earth's natural resilience."},{"type":"paragraph","text":"Which of the above assumptions is/are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage attributes loss of natural resilience to human actions. It does not present global warming as merely a frequently recurring natural event or guarantee safety for small mammals. Only assumption 3 is accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-059","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":59,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\n1. Humans have been the main reason for the large scale extinction of plant species.\\n\\n2. Consumption of food mainly from locally cultivated crops ensures crop diversity.\\n\\n3. The present style of production and distribution of food will finally lead to the problem of food scarcity in the near future.\\n\\n4. Our food security may depend on our ability to preserve the locally cultivated varieties of crops.\\n\\nWhich of the above assumptions are valid ?","options":{"a":"1 and 3","b":"2 and 4","c":"2 and 3","d":"1 and 4"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Food varieties extinction is happening all over the world --- and it is happening fast. For example, of the 7,000 apple varieties that were grown during the nineteenth century, fewer than o hundred remain. In the Philippines, thousands of varieties of rice once thrived; now only up to a hundred are grown there. In China, 90 percent of the wheat varieties cultivated just a century ago have disappeared. Farmers in the past painstakingly bred and developed crops well suited to the peculiarities of their local climate and environment. In the recent past, our heavy dependence on a few high yielding varieties and technology-driven production and distribution of food is causing the dwindling of diversity in food crops. If some mutating crop disease or future climate change decimates the few crop plants we have come to depend on to feed our growing population, we might desperately need some of those varieties we have let go extinct."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Humans have been the main reason for the large scale extinction of plant species."},{"type":"paragraph","text":"2. Consumption of food mainly from locally cultivated crops ensures crop diversity."},{"type":"paragraph","text":"3. The present style of production and distribution of food will finally lead to the problem of food scarcity in the near future."},{"type":"paragraph","text":"4. Our food security may depend on our ability to preserve the locally cultivated varieties of crops."},{"type":"paragraph","text":"Which of the above assumptions are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage links local crops and the preservation of crop diversity, and treats adaptation to changing conditions as important to food security. Assumptions 2 and 4 are the supported pair.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-060","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":60,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"What is X in the sequence 132, 129, 124, 117, 106, 93, X ?","options":{"a":"74","b":"75","c":"76","d":"77"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"What is X in the sequence 132, 129, 124, 117, 106, 93, X ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Subtract consecutive primes: 3,5,7,11,13 and then 17. Thus X=93−17=76.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-061","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":61,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A wall clock moves 10 minutes fast in every 24 hours. The clock was set right to show the correct time at 8:00 a.m. on Monday. When the clock shows the time 6:00 p.m. on Wednesday, what is the correct time ?","options":{"a":"5:36 p.m.","b":"5:30 p.m.","c":"5:24 p.m.","d":"5:18 p.m."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"A wall clock moves 10 minutes fast in every 24 hours. The clock was set right to show the correct time at 8:00 a.m. on Monday. When the clock shows the time 6:00 p.m. on Wednesday, what is the correct time ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The clock gains 10 minutes per real day. Its 58 displayed hours correspond to 58 × 1440/1450=57.6 real hours after Monday 8 a.m., which is Wednesday 5:36 p.m.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-062","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":62,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If the numerator and denominator of a proper fraction are increased by the same positive quantity which is greater than zero, the resulting fraction is","options":{"a":"always less than the original fraction","b":"always greater than the original fraction","c":"always equal to the original fraction","d":"such that nothing can .be claimed definitely"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"If the numerator and denominator of a proper fraction are increased by the same positive quantity which is greater than zero, the resulting fraction is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"For a proper positive fraction a/b, b>a. The difference (a+k)/(b+k)−a/b is k(b−a)/[b(b+k)], which is positive.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-063","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":63,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"What is X in the sequence 4, 196, 16, 144, 36, 100, 64, X ?","options":{"a":"48","b":"64","c":"125","d":"256"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"What is X in the sequence 4, 196, 16, 144, 36, 100, 64, X ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The terms are squared even numbers alternating upwards and downwards: 2²,14²,4²,12²,6²,10²,8²,8². Hence X=64.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-064","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":64,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In a group of 15 people; 7 can read French, 8 can read English while 3 of them can read neither of these two languages. The number of people who can read exactly one language is","options":{"a":"10","b":"9","c":"5","d":"4"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"In a group of 15 people; 7 can read French, 8 can read English while 3 of them can read neither of these two languages. The number of people who can read exactly one language is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Twelve people read at least one language. The overlap is 7+8−12=3, so exactly one language is 12−3=9.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-065","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":65,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A printer numbers the pages of a book starting with 1 and uses 3089 digits in all. How many pages does the book have ?","options":{"a":"1040","b":"1048","c":"1049","d":"1050"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"A printer numbers the pages of a book starting with 1 and uses 3089 digits in all. How many pages does the book have ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Pages 1–999 use 9+180+2700=2889 digits. The remaining 200 digits number 50 four-digit pages, so the final page is 1049.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-066","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":66,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following sequence that follows some arrangement :\\n\\nc_accaa_aa_bc_b\\n\\nThe letters that appear in the gaps are","options":{"a":"abba","b":"cbbb","c":"bbbb","d":"cccc"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Consider the following sequence that follows some arrangement :"},{"type":"paragraph","text":"c_accaa_aa_bc_b"},{"type":"paragraph","text":"The letters that appear in the gaps are"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Insert c,b,b,b to obtain the five-letter groups ccacc, aabaa and bbcbb. Each group follows the repeated-letter pattern XXYXX.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-067","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":67,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A family has two children along with their parents. The average of the weights of the children and their mother is 50 kg. The average of the weights of the children and their father is 52 kg. If the weight of the father is 60 kg, then what is the weight of the mother ?","options":{"a":"48 kg","b":"50 kg","c":"52 kg","d":"54 kg"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"A family has two children along with their parents. The average of the weights of the children and their mother is 50 kg. The average of the weights of the children and their father is 52 kg. If the weight of the father is 60 kg, then what is the weight of the mother ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Children plus mother weigh 150 kg; children plus father weigh 156 kg. The father is 6 kg heavier, so the mother weighs 60−6=54 kg.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-068","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":68,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Suppose you have sufficient amount of rupee currency in three denominations : Rs. 1, Rs. 10 and Rs. 50. In how many different ways can you pay a bill of Rs. 107 ?","options":{"a":"16","b":"17","c":"18","d":"19"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Suppose you have sufficient amount of rupee currency in three denominations : Rs. 1, Rs. 10 and Rs. 50. In how many different ways can you pay a bill of Rs. 107 ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Using zero, one or two Rs. 50 notes leaves 11, 6 or 1 choices for the number of Rs. 10 notes. The Rs. 1 notes fill the balance, giving 11+6+1=18 ways.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-069","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":69,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"'A' started from his house and walked 20 m towards East, where his friend 13' joined him. They together walked 10 m in the same direction. Then 'A' turned left while 'B' turned right and travelled 2 m and 8 m respectively. Again 'B' turned left to travel 4 m followed by 5 m to his right to reach his office. 'A' turned right and travelled 12 m to reach his office. What is the shortest distance between the two offices ?","options":{"a":"15 m","b":"17 m","c":"19 m","d":"20 m"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"'A' started from his house and walked 20 m towards East, where his friend 13' joined him. They together walked 10 m in the same direction. Then 'A' turned left while 'B' turned right and travelled 2 m and 8 m respectively. Again 'B' turned left to travel 4 m followed by 5 m to his right to reach his office. 'A' turned right and travelled 12 m to reach his office. What is the shortest distance between the two offices ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Take the house as (0,0). A’s office is (42,2) and B’s is (34,−13). Their separation is sqrt(8²+15²)=17 m.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-070","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":70,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider two statements S1 and S2 followed by a question:\\n\\nS1: p and q both are prime numbers.\\n\\nS2: p + q is an odd integer.\\n\\nQuestion: Is pq an odd integer?\\n\\nWhich one of the following is correct ?","options":{"a":"S1 alone is sufficient to answer the question","b":"S2 alone is sufficient to answer the question","c":"Both S1 and S2 taken together are not sufficient to answer the question","d":"Both S1 and S2 are necessary to answer the question"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Consider two statements S1 and S2 followed by a question:"},{"type":"paragraph","text":"S1: p and q both are prime numbers."},{"type":"paragraph","text":"S2: p + q is an odd integer."},{"type":"paragraph","text":"Question: Is pq an odd integer?"},{"type":"paragraph","text":"Which one of the following is correct ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"An odd sum of two integers means one is even and the other odd; their product is therefore even. S2 alone answers the question negatively, without requiring primality.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-071","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":71,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Which year has the same calendar as that of 2009 ?","options":{"a":"2018","b":"2017","c":"2016","d":"2015"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Which year has the same calendar as that of 2009 ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"A matching ordinary-year calendar needs the same weekday on 1 January. The accumulated weekday shift from 2009 to 2015 is seven days, so 2015 matches.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-072","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":72,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Number 136 is added to 5B7 and the sum obtained is 7A3, where A and B are integers. It is given that 7A3 is exactly divisible by 3. The only possible value of B is","options":{"a":"2","b":"5","c":"7","d":"8"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"paragraph","text":"Number 136 is added to 5B7 and the sum obtained is 7A3, where A and B are integers. It is given that 7A3 is exactly divisible by 3. The only possible value of B is"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"From 5B7+136=7A3, the units carry gives A=B−6. Among the possible digits, divisibility by 3 requires A=2, so B=8.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-073","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":73,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is the main idea that we can infer from the passage ?","options":{"a":"Untouchability in India has not been taken seriously by political theorists.","b":"Historical injustice is inevitable in any society and is always beyond repair.","c":"Social discrimination and deprivation have their roots in bad economies.","d":"It is difficult, if not impossible, to repair every manifestation of historical injustice."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Political theorists no doubt have to take history of injustice, for example, untouchability, seriously. The concept of historical injustice takes note of a variety of historical wrongs that continue into the present in some form or the other and tend to resist repair. Two reasons might account for resistance to repair. One, not only are the roots of injustice buried deep in history, injustice itself constitutes economic structures of exploitation, ideologies of discrimination and modes of representation. Two, the category of historical injustice generally extends across a number of wrongs such as economic deprivation, social discrimination and lack of recognition. This category is complex, not only because of the overlap between a number of wrongs, but because one or the other wrong, generally discrimination, tends to acquire partial autonomy from others. This is borne out by the history of repair in India."},{"type":"paragraph","text":"What is the main idea that we can infer from the passage ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage explains the overlapping and partly autonomous forms of historical injustice. This makes complete repair difficult, without claiming that every injustice is inevitable or beyond repair.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-074","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":74,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\n1. Removal of economic discrimination leads to removal of social discrimination.\\n\\n2. Democratic polity is the best way to repair historical wrongs.\\n\\nWhich of the above assumptions is/are valid ?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Political theorists no doubt have to take history of injustice, for example, untouchability, seriously. The concept of historical injustice takes note of a variety of historical wrongs that continue into the present in some form or the other and tend to resist repair. Two reasons might account for resistance to repair. One, not only are the roots of injustice buried deep in history, injustice itself constitutes economic structures of exploitation, ideologies of discrimination and modes of representation. Two, the category of historical injustice generally extends across a number of wrongs such as economic deprivation, social discrimination and lack of recognition. This category is complex, not only because of the overlap between a number of wrongs, but because one or the other wrong, generally discrimination, tends to acquire partial autonomy from others. This is borne out by the history of repair in India."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Removal of economic discrimination leads to removal of social discrimination."},{"type":"paragraph","text":"2. Democratic polity is the best way to repair historical wrongs."},{"type":"paragraph","text":"Which of the above assumptions is/are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage says discrimination can have autonomy from economic deprivation, so eliminating one need not eliminate the other. It also does not rank democratic polity as the best repair mechanism. Neither assumption follows.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-075","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":75,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\n1. A society without well educated people cannot be transformed into a modern society.\\n\\n2. Without acquiring culture, a person's education is not complete.\\n\\nWhich of the above assumptions is/are valid ?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Education plays a great transformatory role in life, particularly so in this rapidly changing and globalizing world. Universities are the custodians of the intellectual capital and promoters of culture and specialized knowledge. Culture is an activity of thought, and receptiveness to beauty and human feelings. A merely well informed man is only a bore on God's earth. What we should aim at is producing men who possess both culture and expert knowledge. Their expert knowledge will give them a firm ground to start from and their culture will lead them as deep as philosophy and as high as art. Together it will impart meaning to human existence."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. A society without well educated people cannot be transformed into a modern society."},{"type":"paragraph","text":"2. Without acquiring culture, a person's education is not complete."},{"type":"paragraph","text":"Which of the above assumptions is/are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The explicit argument is that culture and specialised knowledge together give education its meaning. It does not establish educated people as a necessary condition for every modern social transformation. Only assumption 2 is accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-076","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":76,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\n1. Large scale soil erosion is a major reason for widespread food insecurity in the world.\\n\\n2. Soil erosion is mainly anthropogenic.\\n\\n3. Sustainable management of soils helps in combating climate change.\\n\\nWhich of the above assumptions is/are valid ?","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Soil, in which nearly all our food grows, is a living resource that takes years to form. Yet it can vanish in minutes. Each year 75 billion tonnes of fertile soil is lost to erosion. That is alarming — and not just for food producers. Soil can trap huge quantities of carbon dioxide in the form of organic carbon and prevent it from escaping into the atmosphere."},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Large scale soil erosion is a major reason for widespread food insecurity in the world."},{"type":"paragraph","text":"2. Soil erosion is mainly anthropogenic."},{"type":"paragraph","text":"3. Sustainable management of soils helps in combating climate change."},{"type":"paragraph","text":"Which of the above assumptions is/are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage links sustainable soil management with climate-change mitigation. It does not establish the stated scale of global food insecurity or that erosion is mainly human-caused. Only assumption 3 is accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-077","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":77,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"On the basis of the above passage, the following assumptions have been made :\\n\\n1. Economic power is the only reason for the existence of inequality in a society.\\n\\n2. Inequality of different kinds, income, wealth, etc, reinforces power.\\n\\n3. Economic power can be analysed more through its effects than by direct empirical methods.\\n\\nWhich of the above assumptions is/are valid ?","options":{"a":"1 and 2 only","b":"3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Inequality is visible, even statistically measurable in many instances, but the economic power that drives it is invisible and not measurable... Like the force of gravity, power is the organising principle of inequality, be it of income, or wealth, gender, race, religion and region. Its effects are seen in a pervasive manner in all spheres, but the ways in which economic power pulls and tilts visible economic variables remain invisibly obscure,"},{"type":"paragraph","text":"On the basis of the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Economic power is the only reason for the existence of inequality in a society."},{"type":"paragraph","text":"2. Inequality of different kinds, income, wealth, etc, reinforces power."},{"type":"paragraph","text":"3. Economic power can be analysed more through its effects than by direct empirical methods."},{"type":"paragraph","text":"Which of the above assumptions is/are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage treats economic power through its observable effects when direct measurement is difficult. It does not reduce all inequality to economic power or assert that all forms of inequality reinforce it. Only assumption 3 is accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-078","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":78,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical and rational inference that can be made from the above passage ?","options":{"a":"Farmers who modernize their methods and diversify their fields will be. in an advantageous position in future.","b":"Climate change will adversely affect the crop diversity.","c":"Shifting major crops to new croplands will lead to a great increase in the total area under cultivation and thus an increase in overall agricultural production.","d":"Climate change is the most important factor affecting the agricultural economy in the future."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Climate change may actually benefit some plants by lengthening growing seasons and increasing carbon dioxide. Yet other effects of a warmer world, such as more pests, droughts, and flooding, will be less benign. How will the world adapt ? Researchers project that by 2050, suitable croplands for four commodities — maize, potatoes, rice and wheat — will shift, in some cases pushing farmers to plant new crops. Some farmlands may benefit from warming, but others won't. Climate alone does not dictate yields; political shifts, global \\"demand, and agricultural practices will influence how farms fare in the future."},{"type":"paragraph","text":"Which one of the following is the most logical and rational inference that can be made from the above passage ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The passage emphasises adaptation in farming under changing climatic conditions. Modernising methods and diversifying fields can therefore place farmers in a better position; the stronger universal claims are not established.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-079","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":79,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the most logical, scientific and rational inference that can be made from the above passage ?","options":{"a":"Different species having similar structure of hands is an example of biodiversity.","b":"Limbs being used by different species for different kinds of work is an example of biodiversity.","c":"Man and the aforementioned animals having similar structure of limbs is an example of coincidence in evolution.","d":"Man and the aforementioned animals have a shared evolutionary history."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"A bat's .wings may look like sheets of skin. But underneath, a bat has the same five fingers as an orangutan or a human, as well as a wrist connected to the same cluster of wrist bones connected to the same long bones of the arm. What can be more curious than that the hand of a man, formed for grasping, that of a mole for digging, the leg of the horse, the-paddle of the porpoise, and the wing of the bat, should all be constructed on the some pattern ?"},{"type":"paragraph","text":"Which one of the following is the most logical, scientific and rational inference that can be made from the above passage ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"Similar underlying limb structures in humans and other animals point to common ancestry. Different present-day uses do not make the similarity a coincidence.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}},{"id":"upsc-2019-prelims-csat-b-080","year":2019,"stage":"CSAT","paper":"CSAT Paper II","number":80,"booklet":"B","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Based on the above passage, the following assumptions have been made :\\n\\n1. Global warming has a bearing on the planet's biological evolution.\\n\\n2. Separation of land masses causes the release of huge quantities of carbon into the atmosphere.\\n\\n3. Increased warming of Earth's atmosphere can change the composition of its flora and fauna.\\n\\n4. The present man-made global warming will finally lead to conditions similar to those which happened 56 million years ago.\\n\\nWhich of the assumptions given above are valid ?","options":{"a":"1 and 2","b":"3 and 4","c":"1 and 3","d":"2 and 4"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/upsc-pre/papers/2019-csat","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2","page":0,"blocks":[{"type":"passage","text":"Around 56 million years ago, the Atlantic Ocean had not fully opened and animals, perhaps including our primate ancestors, could walk from Asia to North America through Europe and across Greenland. Earth was warmer than it is today, but as the Palaeocene epoch gave way to Eocene, it was about to get much warmer still —rapidly and radically. The cause was a massive geologically sudden release of carbon. During this period called Palaeocene - Eocene Thermal Maximum or PETM, the carbon injected into the atmosphere was roughly the amount that Would be injected today if humans burned all the Earth's reserves of coal, oil and natural gas. The PETM lasted for about 1,50,000 years, until the excess carbon was reabsorbed. It brought on drought, floods, insect plagues and a few extinctions. Life on Earth survived — indeed, it prospered — but it was drastically different."},{"type":"paragraph","text":"Based on the above passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Global warming has a bearing on the planet's biological evolution."},{"type":"paragraph","text":"2. Separation of land masses causes the release of huge quantities of carbon into the atmosphere."},{"type":"paragraph","text":"3. Increased warming of Earth's atmosphere can change the composition of its flora and fauna."},{"type":"paragraph","text":"4. The present man-made global warming will finally lead to conditions similar to those which happened 56 million years ago."},{"type":"paragraph","text":"Which of the assumptions given above are valid ?"}],"difficultyLabel":"Moderate","sourceTitle":"UPSC CSE 2019 CSAT Paper II · Series B","explanation":{"justification":"The example links warming with biological change and altered flora and fauna. It does not support land separation as the stated carbon cause or guarantee identical future conditions. Assumptions 1 and 3 are accepted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2019 final answer key · Series B","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2019-CSAT.pdf#page=2"}]}}]`);export{e as p};
